def direction(value,unit):
    if abs(value)<0.00005:return f'0 {unit} (aligned)'
    return f'{abs(value):.3f} {unit} '+('LEFT' if value>0 else 'RIGHT')

def measurements(s):
    k,r=s['kart'],s['road']
    lines=[f"MEASURED NOW: road tangent is {direction(r['road_vs_kart_deg'],'degrees')} from the kart NOSE.",
           f"Actual wheels: {direction(k['steering_deg'],'degrees')}. Actual body yaw: {direction(k['yaw_deg_s'],'degrees per second')}.",
           f"Speed: {k['speed_m_s']:.3f} m/s. Centre offset: {direction(r['offset_m'],'metres')}.",
           f"Edge clearances: LEFT {r['left_edge_clearance_m']:.3f} m; RIGHT {r['right_edge_clearance_m']:.3f} m."]
    for row in r['preview']:
        if row[0] in [3,6,10]:lines.append(f"Road centre at arc {row[0]:g} m: {row[1]:.3f} m along the nose axis, {direction(row[2],'m')} across that axis.")
    g=s.get('next_gate',{})
    if g.get('known'):
        position='approach side' if g['signed_plane_m']<=0 else 'forward side'
        lines.append(f"Gate {g['index']} is STILL REQUIRED. Its plane coordinate is {g['signed_plane_m']:.4f} m ({position}); its centre bearing is {direction(g['bearing_to_centre_deg'],'degrees')}, range {g['range_m']:.3f} m. Credit requires a negative-to-positive plane crossing within the gate span.")
    return ' '.join(lines)+' These are current measurements, not selected controls. '
